parameters.jsCode:
return items.map(item => {
  const dataSaida = item.json.body?.data;
  if (!dataSaida || !dataSaida.created_time) {
    return item;
  }

  const d = new Date(dataSaida.created_time);

  // Subtrai 3 horas do horário atual
  d.setHours(d.getHours() - 3);

  // Agora formatamos manualmente
  const dia = String(d.getDate()).padStart(2, '0');
  const mes = String(d.getMonth() + 1).padStart(2, '0');
  const ano = d.getFullYear();
  const hora = String(d.getHours()).padStart(2, '0');
  const minuto = String(d.getMinutes()).padStart(2, '0');

  const formatted = `${dia}/${mes}/${ano} ${hora}:${minuto}`;

  dataSaida.formattedDate = formatted;

  return item;
});

